"""Random phrases: half are built as a mirrored palindrome with random
punctuation and case sprinkled in, half are random strings."""


def generate(rng, count):
    return [_case(rng, i + 1) for i in range(count)]


def _noise(rng, text):
    out = []
    for ch in text:
        if rng.random() < 0.3:
            out.append(rng.choice(" ,.!-"))
        out.append(ch.upper() if rng.random() < 0.5 else ch)
    return "".join(out)


def _case(rng, index):
    half = "".join(rng.choice("abcde12") for _ in range(rng.randint(1, 6)))
    middle = rng.choice(["", "x"])
    base = half + middle + half[::-1]
    if rng.random() < 0.5:
        # break exactly one letter so it is a near-miss
        pos = rng.randrange(len(base))
        base = base[:pos] + ("z" if base[pos] != "z" else "y") + base[pos + 1:]
    line = _noise(rng, base)
    return {"name": "phrase #%d" % index, "stdin": line + "\n"}
